For iTarget=1:1:$L(..TargetConfigNames, ",") { Set tOneTarget=$ZStrip($P(..TargetConfigNames,",",iTarget),"<>W") Continue:""=tOneTarget $$$TRACE("Sending data to: " _ tOneTarget) Set tSC1=..SendRequestAsync(tOneTarget,pResponse) Set:$$$ISERR(tSC1) tSC=$$$ADDSC(tSC,tSC1) } Set pResponse1=tSC Quit tSC

 	Do ##super(.pArray,pItem)
